import{_ as t,o as d,c as s,am as f}from"./chunks/framework.ZxETiGz0.js";const v=JSON.parse('{"title":"مدونة لغة ص","description":"آخر أخبار وتحديثات لغة ص — مقالات تقنية وأخبار المجتمع","frontmatter":{"title":"مدونة لغة ص","description":"آخر أخبار وتحديثات لغة ص — مقالات تقنية وأخبار المجتمع"},"headers":[],"relativePath":"blog.md","filePath":"blog.md","lastUpdated":null}'),e={name:"blog.md"};function l(o,a,b,r,p,i){return d(),s("div",null,[...a[0]||(a[0]=[f('<h1 id="مدونة-لغة-ص" tabindex="-1" data-v-f3fb242d>مدونة لغة ص <a class="header-anchor" href="#مدونة-لغة-ص" aria-label="Permalink to &quot;مدونة لغة ص&quot;" data-v-f3fb242d>​</a></h1><p data-v-f3fb242d>آخر المقالات التقنية والتحديثات وأخبار المجتمع.</p><hr data-v-f3fb242d><ul class="blog-list" data-v-f3fb242d><li data-v-f3fb242d><a class="post-title" href="/blog/v1-release" data-v-f3fb242d> 🎉 الإعلان عن الإصدار الرسمي الأول — لغة ص v1.0.0 </a><p class="post-meta" data-v-f3fb242d>9 أبريل 2025 · فريق لغة ص</p><p class="post-summary" data-v-f3fb242d> يسعدنا الإعلان عن الإصدار الرسمي الأول للغة ص — أول لغة برمجة عربية حديثة تدعم المفسّر والمترجم الأصيل وخادم LSP... </p></li><li data-v-f3fb242d><a class="post-title" href="/blog/llvm-compiler" data-v-f3fb242d> 🚀 كيف بنينا مترجم لغة ص باستخدام LLVM 18 </a><p class="post-meta" data-v-f3fb242d>15 مارس 2025 · قسم الهندسة</p><p class="post-summary" data-v-f3fb242d> رحلة بناء المترجم sadc من AST إلى SIR ثم LLVM IR ثم ملف تنفيذي أصيل، والتحديات التي واجهناها في دعم النصوص العربية RTL... </p></li><li data-v-f3fb242d><a class="post-title" href="/blog/arabic-programming" data-v-f3fb242d> 🌍 لماذا تحتاج البرمجة إلى لغة عربية؟ </a><p class="post-meta" data-v-f3fb242d>1 فبراير 2025 · مقال رأي</p><p class="post-summary" data-v-f3fb242d> تحليل مفصّل حول أثر اللغة على التفكير البرمجي، وكيف أن البرمجة بلغتك الأم تُحسّن القدرة الإبداعية وتُسرّع التعلم... </p></li><li data-v-f3fb242d><a class="post-title" href="/blog/lsp-arabic" data-v-f3fb242d> 🛠️ بناء خادم LSP يدعم العربية </a><p class="post-meta" data-v-f3fb242d>20 ديسمبر 2024 · قسم الأدوات</p><p class="post-summary" data-v-f3fb242d> دليل تقني لبناء sad-lsp — خادم بروتوكول اللغة الذي يوفر إكمالاً تلقائياً وتشخيصاً للأخطاء في الكود العربي مع الأخذ بعين الاعتبار خصائص RTL... </p></li><li data-v-f3fb242d><a class="post-title" href="/blog/stdlib-design" data-v-f3fb242d> 📦 تصميم مكتبة قياسية عربية </a><p class="post-meta" data-v-f3fb242d>5 نوفمبر 2024 · هندسة المكتبات</p><p class="post-summary" data-v-f3fb242d> كيف صمّمنا المكتبة القياسية للغة ص — من core وio وmath إلى network وgraphics، مع الحفاظ على اتساق المصطلحات العربية... </p></li></ul><hr data-v-f3fb242d><h2 id="اشترك-في-النشرة-الإخبارية" tabindex="-1" data-v-f3fb242d>اشترك في النشرة الإخبارية <a class="header-anchor" href="#اشترك-في-النشرة-الإخبارية" aria-label="Permalink to &quot;اشترك في النشرة الإخبارية&quot;" data-v-f3fb242d>​</a></h2><p data-v-f3fb242d>احصل على آخر تحديثات لغة ص مباشرة في بريدك.</p><div class="newsletter" data-v-f3fb242d><input type="email" placeholder="بريدك الإلكتروني" class="email-input" data-v-f3fb242d><button class="subscribe-btn" data-v-f3fb242d>اشترك</button></div><hr data-v-f3fb242d><h2 id="ساهم-بمقال" tabindex="-1" data-v-f3fb242d>ساهم بمقال <a class="header-anchor" href="#ساهم-بمقال" aria-label="Permalink to &quot;ساهم بمقال&quot;" data-v-f3fb242d>​</a></h2><p data-v-f3fb242d>هل لديك تجربة أو مقال تريد مشاركته مع مجتمع لغة ص؟</p><p data-v-f3fb242d><a href="https://github.com/sad-lang/sad-language/tree/main/website/docs/blog" target="_blank" rel="noreferrer" data-v-f3fb242d>افتح Pull Request في GitHub ←</a></p>',12)])])}const n=t(e,[["render",l],["__scopeId","data-v-f3fb242d"]]);export{v as __pageData,n as default};
